/* Portable server features. The public Sites preview never stores credentials. */
(() => {
  'use strict';
  const X=R.plus,E=R.esc;
  const P=R.platform={group:'all',draft:{title:'',modality:'CT',lang:R.lang,html:''},settings:null,settingsError:'',loading:false};
  const copy={
    payments:['Ödəniş ayarları','Настройки оплаты','Payment settings'],viewerSettings:['RADAZ bağlantısı','Подключение RADAZ','RADAZ connection'],
    adminOnly:['Yalnız saytın sahib administratoru','Только администратор-владелец сайта','Site owner administrator only'],
    serverNeeded:['Bu önizləmədə bank məlumatları saxlanmır. Qorunan ayarlar üçün saytın server versiyasına daxil olun.','В этом предпросмотре банковские данные не сохраняются. Войдите в серверную версию сайта.','This preview does not store bank details. Sign in to the server version of the site.'],
    images:['Görüntülər','Изображения','Images'],report:['Rapor yaz','Написать заключение','Write report'],openRadaz:['RADAZ-da görüntüləri aç','Открыть изображения в RADAZ','Open images in RADAZ'],
    desktop:['RADAZ proqramını başlat','Запустить программу RADAZ','Launch RADAZ desktop'],back:['Kabinetə qayıt','Вернуться в кабинет','Back to workspace'],
    separate:['Görüntülər və rapor ayrı səhifələrdə açılır. Hər ikisini yanaşı istifadə edə bilərsiniz.','Изображения и заключение открываются на отдельных страницах. Их можно расположить рядом.','Images and reports open on separate pages. You can use them side by side.'],
    viewerHint:['DICOM müayinəsi səlahiyyətiniz yoxlanıldıqdan sonra RADAZ-a ötürülür.','DICOM-исследование передаётся в RADAZ после проверки доступа.','Your access is checked before the DICOM study is transferred to RADAZ.'],
    disconnected:['RADAZ ünvanı hələ qoşulmayıb. Administrator bağlantı ayarlarından ünvanı əlavə edə bilər.','Адрес RADAZ ещё не подключён. Администратор может указать его в настройках.','The RADAZ address is not configured yet. The administrator can add it in connection settings.'],
    sample:['Bu demo müraciətdə real DICOM arxivi yoxdur.','В этой демозаявке нет DICOM-архива.','This demo case contains no DICOM archive.'],
    all:['Bütün qruplar','Все группы','All groups'],newTemplate:['Yeni şablon','Новый шаблон','New template'],edit:['Düzəliş et','Редактировать','Edit'],save:['Saxla','Сохранить','Save'],saved:['Saxlanıldı','Сохранено','Saved'],
    title:['Şablon adı','Название шаблона','Template name'],group:['Müayinə qrupu','Группа исследований','Study group'],body:['Şablon mətni','Текст шаблона','Template content'],empty:['Bu qrupda şablon yoxdur.','В этой группе нет шаблонов.','No templates in this group.'],
    templateLibrary:['Şablon kitabxanası','Библиотека шаблонов','Template library'],insert:['Şablonu daxil et','Вставить шаблон','Insert template'],
    bank:['Bank məlumatları','Банковские реквизиты','Bank details'],keys:['Ödəniş sistemi açarları','Ключи платёжной системы','Payment provider keys'],
    provider:['Ödəniş üsulu','Способ оплаты','Payment method'],environment:['Mühit','Среда','Environment'],merchant:['Merchant ID','Merchant ID','Merchant ID'],bankName:['Bankın adı','Название банка','Bank name'],holder:['Hesab sahibi','Владелец счёта','Account holder'],tax:['VÖEN','ИНН','Tax ID'],notes:['Qeydlər','Примечания','Notes'],
    keyNote:['Açarlar şifrələnərək saxlanılır. Boş saxlasanız əvvəlki açar qorunur; mövcud açar brauzerə qaytarılmır.','Ключи сохраняются в зашифрованном виде. Пустое поле сохраняет прежний ключ; ключ не возвращается в браузер.','Keys are encrypted at rest. Leave a field blank to retain its key; saved keys are never returned to the browser.'],
    keySaved:['Açar saxlanılıb','Ключ сохранён','Key saved'],notSet:['Daxil edilməyib','Не задано','Not set'],clear:['Saxlanmış açarı sil','Удалить сохранённый ключ','Remove saved key'],
    noCharge:['Bu ayarlar məlumatları saxlayır. Kartla ödəniş qəbul etmək üçün seçilən provayderin inteqrasiyası ayrıca qoşulmalıdır.','Эти настройки сохраняют реквизиты. Для приёма платежей необходимо подключить выбранного провайдера.','These settings store your details. The selected provider must be integrated before card payments can be accepted.'],
    webUrl:['RADAZ Viewer ünvanı','Адрес RADAZ Viewer','RADAZ Viewer URL'],desktopEnable:['Quraşdırılmış RADAZ proqramına keçidi göstər','Показать запуск установленного RADAZ','Show the installed RADAZ launcher'],
    desktopNote:['Kompüterdə RADAZ keçid modulu quraşdırılmalıdır. Brauzer proqramı açmaq üçün təsdiq istəyə bilər.','На компьютере нужен модуль запуска RADAZ. Браузер может запросить подтверждение.','The RADAZ launch module must be installed on the computer. Your browser may ask before opening the application.'],
    urlNote:['Eyni hostinq üçün /viewer/ ünvanını yaza bilərsiniz. Mövcud RADAZ-a müayinə qəbuledicisi əlavə edilməlidir.','Для общего хостинга можно указать /viewer/. В RADAZ должен быть подключён модуль приёма исследования.','Use /viewer/ on the same host. The study receiver must be integrated into RADAZ.'],
    submit:['Müraciəti göndər','Отправить заявку','Submit request'],requestReceived:['Müraciətiniz qəbul edildi.','Ваша заявка принята.','Your request was received.'],notCharged:['Kartdan pul tutulmayıb. Ödəniş və xidmətin təsdiqi ayrıca razılaşdırılır.','Средства с карты не списаны. Оплата и подтверждение услуги согласуются отдельно.','No card was charged. Payment and service confirmation are arranged separately.'],
    ready:['Rapor və görüntü iş mühiti','Работа с заключениями и изображениями','Reporting and imaging workspace'],loginFirst:['Bu bölməni açmaq üçün daxil olun.','Войдите, чтобы открыть этот раздел.','Sign in to open this section.'],
    loading:['Yüklənir…','Загрузка…','Loading…'],retry:['Yenidən yoxla','Повторить','Retry'],bold:['Qalın','Полужирный','Bold'],italic:['Kursiv','Курсив','Italic'],underline:['Altıxətli','Подчёркнутый','Underline'],list:['Siyahı','Список','List'],table:['Cədvəl','Таблица','Table'],undo:['Geri al','Отменить','Undo'],redo:['İrəli al','Повторить','Redo'],
    confirmSubmit:['Məlumatları yoxladım və müraciəti göndərməyə razıyam.','Я проверил данные и согласен отправить заявку.','I checked the details and consent to submitting this request.'],
    archive:['Arxivi yüklə','Скачать архив','Download archive'],connectionReady:['Bağlantı ayarları saxlanıldı','Настройки подключения сохранены','Connection settings saved']
  };
  const t=key=>copy[key]?.[{az:0,ru:1,en:2}[R.lang]??0]||key;
  const groupName=key=>({CT:['KT','КТ','CT'],MR:['MRT','МРТ','MRI'],CR:['Rentgen','Рентген','X-ray'],US:['USM','УЗИ','Ultrasound']}[key]?.[{az:0,ru:1,en:2}[R.lang]??0]||key);
  const live=()=>!!window.RADAZ_PRODUCTION;
  const field=(label,name,value='',type='text',extra='')=>`<label class="field">${E(label)}<input name="${name}" type="${type}" value="${E(value)}" ${extra}></label>`;
  const button=(label,action,extra='',cls='btn btn-outline btn-sm')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${E(label)}</button>`;
  const groupOptions=(selected)=>['CT','MR','CR','US'].map(k=>`<option value="${k}" ${k===selected?'selected':''}>${groupName(k)}</option>`).join('');
  const tabs=(action,selected)=>`<div class="p-group-tabs" role="group" aria-label="${t('group')}">${['all','CT','MR','CR','US'].map(k=>button(k==='all'?t('all'):groupName(k),action,`data-group="${k}" aria-pressed="${selected===k}"`)).join('')}</div>`;
  const loadSettings=async()=>{if(P.loading||!live()||R.state.user?.role!=='admin')return;P.loading=true;P.settingsError='';try{P.settings=await R.request('/admin/payment-settings');P.viewer=await R.request('/admin/viewer-settings');}catch(e){P.settingsError=e.message;}finally{P.loading=false;if(R.state.route.startsWith('/admin/'))R.render();}};
  const adminShell=(title,html)=>X.shell(title,`<div class="dashboard-heading"><div><span class="eyebrow">RADAZ · ${t('adminOnly')}</span><h1>${title}</h1></div></div><nav class="p-admin-tabs"><a href="#/admin/payments">${t('payments')}</a><a href="#/admin/viewer">${t('viewerSettings')}</a></nav>${html}`);
  P.adminPage=()=>{
    if(!R.state.user)return R.header()+R.authPage(false)+R.footer();
    const heading=t(R.state.route==='/admin/viewer'?'viewerSettings':'payments');
    if(R.state.user.role!=='admin')return `<main class="container page">${R.note(t('adminOnly'),'lock')}<a href="#/dashboard">${t('back')}</a></main>`;
    if(!live())return adminShell(heading,R.note(t('serverNeeded'),'lock'));
    if(P.settingsError)return adminShell(heading,`${R.note(E(P.settingsError),'info')}${button(t('retry'),'pReloadSettings')}`);
    if(!P.settings){queueMicrotask(loadSettings);return adminShell(heading,`<p role="status">${t('loading')}</p>`);}
    if(R.state.route==='/admin/viewer')return adminShell(heading,`<section class="card p-settings"><form data-form="pViewer">${field(t('webUrl'),'web_url',P.viewer?.web_url||'','text','placeholder="https://…/viewer/" maxlength="2000"')}<p class="muted-text">${t('urlNote')}</p><label class="check-field"><input name="desktop_enabled" type="checkbox" ${P.viewer?.desktop_enabled?'checked':''}><span>${t('desktopEnable')}</span></label><p class="muted-text">${t('desktopNote')}</p><button class="btn btn-primary" type="submit">${t('save')}</button></form></section>`);
    const v=P.settings.values||{};
    return adminShell(heading,`<form data-form="pPayments" autocomplete="off"><div class="p-settings-grid"><section class="card"><h2>${t('bank')}</h2><div class="form-grid"><label class="field">${t('provider')}<select name="provider">${[['unconfigured','—'],['bank_transfer',t('bank')],['epoint','Epoint'],['other','Digər / Other']].map(([k,label])=>`<option value="${k}" ${v.provider===k?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">${t('environment')}<select name="environment"><option value="test" ${v.environment!=='live'?'selected':''}>Test</option><option value="live" ${v.environment==='live'?'selected':''}>Live</option></select></label>${field(t('merchant'),'merchant_id',v.merchant_id)}${field(t('bankName'),'bank_name',v.bank_name)}${field(t('holder'),'account_holder',v.account_holder)}${field('IBAN','iban',v.iban)}${field('SWIFT / BIC','swift',v.swift)}${field(t('tax'),'tax_id',v.tax_id)}<label class="field">Valyuta / Currency<select name="currency">${['AZN','USD','EUR'].map(k=>`<option ${v.currency===k?'selected':''}>${k}</option>`).join('')}</select></label></div><label class="field">${t('notes')}<textarea name="notes" rows="3" maxlength="2000">${E(v.notes||'')}</textarea></label></section><section class="card"><h2>${t('keys')}</h2><p>${t('keyNote')}</p>${['api_key','secret_key','webhook_secret'].map((key,i)=>`<div class="p-secret">${field(['API key','Secret key','Webhook secret'][i],key,'','password','autocomplete="new-password" maxlength="4096"')}<small>${t(P.settings.secrets?.[key]?'keySaved':'notSet')}</small>${P.settings.secrets?.[key]?`<label class="check-field"><input type="checkbox" name="clear_${key}"><span>${t('clear')}</span></label>`:''}</div>`).join('')}</section></div>${R.note(t('noCharge'),'info')}<button type="submit" class="btn btn-primary">${t('save')}</button></form>`);
  };
  R.forms.pPayments=async(d,f)=>{const clear_secrets=['api_key','secret_key','webhook_secret'].filter(k=>f.elements['clear_'+k]?.checked);await R.request('/admin/payment-settings',{method:'PUT',body:{...d,clear_secrets}});f.reset();P.settings=null;await loadSettings();R.toast(t('saved'));};
  R.forms.pViewer=async(d,f)=>{await R.request('/admin/viewer-settings',{method:'PUT',body:{web_url:d.web_url,desktop_enabled:f.elements.desktop_enabled.checked}});P.settings=null;await loadSettings();R.config=await R.request('/config');R.toast(t('connectionReady'));};
  R.actions.pReloadSettings=()=>{P.settings=null;P.settingsError='';return loadSettings();};
  const originalWorkspace=R.workspace;
  R.workspace=()=>{
    const c=R.state.selectedCase;if(!c)return originalWorkspace();
    const patient=E(`${c.patient.last_name} ${c.patient.first_name}`),caseId=encodeURIComponent(c.id),isImages=R.state.route.startsWith('/images/');
    const nav=`<nav class="p-case-nav"><a class="${!isImages?'active':''}" href="#/report/${caseId}" ${isImages?'target="_blank" rel="noopener"':''}>${R.icon('file',18)} ${t('report')}</a><a class="${isImages?'active':''}" href="#/images/${caseId}" ${!isImages?'target="_blank" rel="noopener"':''}>${R.icon('scan',18)} ${t('images')}</a></nav>`;
    if(isImages)return `<div class="workspace-shell p-images"><header class="workspace-top"><a href="#/dashboard">${R.icon('back',18)} ${t('back')}</a>${R.logo(true)}<span>${E(c.id)}</span>${R.languagePicker()}</header>${nav}<main class="container page"><div class="p-imaging-heading"><div><span class="eyebrow">RADAZ VIEWER</span><h1>${patient}</h1><p>${E(c.metadata?.modality||'DICOM')} · ${E(c.metadata?.patient_id||c.id)}</p></div>${R.badge(c.status)}</div><section class="card p-launch-card"><span class="icon-square">${R.icon('scan',32)}</span><h2>${t('openRadaz')}</h2><p>${t('separate')}</p><p class="muted-text">${t('viewerHint')}</p><div class="button-row">${button(t('openRadaz'),'openRadaz',c.sample?'disabled':'','btn btn-primary')}${R.config?.desktop_enabled?button(t('desktop'),'pDesktop',c.sample?'disabled':''):''}${button(t('archive'),'downloadArchive',c.sample?'disabled':'')}</div><div id="p-launch-status" role="status">${c.sample?R.note(t('sample')):!R.config?.viewer_path?R.note(t('disconnected')):''}</div></section><section class="card p-clinical"><h3>${R.t('Pasiyentin şikayəti və sualı')}</h3><p>${E(c.patient.complaints)}</p></section></main></div>`;
    const shell=document.createElement('div');shell.innerHTML=originalWorkspace();shell.querySelector('.dicom-pane')?.remove();shell.querySelector('.workspace-grid')?.classList.add('p-report-only');shell.querySelector('.workspace-top')?.insertAdjacentHTML('afterend',nav);shell.querySelector('.workspace-demo')?.remove();shell.querySelector('.report-heading')?.insertAdjacentHTML('afterend',`<div class="p-report-patient"><strong>${patient}</strong><span>${E(c.metadata?.modality||'DICOM')} · ${E(c.id)}</span></div>`);
    return shell.innerHTML;
  };
  const oldLoadImages=R.loadCaseImages;R.loadCaseImages=c=>R.isCaseRoute(R.state.route)?Promise.resolve():oldLoadImages(c);
  async function launch(desktop=false){
    if(!live())throw Error(t('serverNeeded'));
    const status=R.$('#p-launch-status');status.textContent=t('loading');
    try{
      const result=await R.request(`/cases/${encodeURIComponent(R.state.selectedCase.id)}/viewer-launch`,{method:'POST',body:{}});
      if(desktop){if(!result.desktop_url)throw Error(t('disconnected'));location.href=result.desktop_url;status.textContent=t('viewerHint');}
      else location.assign(result.url);
    }catch(error){status.textContent=error.message;throw error;}
  }
  R.actions.openRadaz=()=>launch(false);R.actions.pDesktop=()=>launch(true);
  function readDraft(){const f=R.$('[data-form="pTemplate"]');if(f)P.draft={...P.draft,title:f.elements.title.value,modality:f.elements.modality.value,lang:f.elements.lang.value,html:R.safeHTML(R.$('#template-editor').innerHTML)};}
  const toolbar=()=>`<div class="p-template-toolbar" role="toolbar" aria-label="${t('body')}">${[['bold','B','bold'],['italic','I','italic'],['underline','U','underline'],['insertUnorderedList','☷','list'],['undo','↶','undo'],['redo','↷','redo']].map(([cmd,label,key])=>`<button type="button" data-template-cmd="${cmd}" aria-label="${t(key)}" title="${t(key)}">${label}</button>`).join('')}<select id="p-template-heading" aria-label="${R.t('Mətn formatı')}"><option value="p">${R.t('Mətn')}</option><option value="h2">H2</option><option value="h3">H3</option></select><button type="button" data-template-cmd="table">${t('table')}</button></div>`;
  X.templatesPage=()=>{
    if(!R.state.user||R.state.user.role!=='doctor')return R.authPage(false);
    const d=P.draft,list=X.templates||[];
    return X.shell(t('templateLibrary'),`<div class="dashboard-heading"><div><span class="eyebrow">RADAZ REPORT</span><h1>${t('templateLibrary')}</h1></div>${button(t('newTemplate'),'pNewTemplate')}</div><div class="p-template-layout"><section class="card"><h2>${t(d.id?'edit':'newTemplate')}</h2><form data-form="pTemplate">${field(t('title'),'title',d.title,'text','required maxlength="150"')}<div class="form-grid"><label class="field">${t('group')}<select name="modality">${groupOptions(d.modality)}</select></label><label class="field">${R.t('Dil')}<select name="lang">${[['az','Azərbaycan'],['ru','Русский'],['en','English']].map(([k,n])=>`<option value="${k}" ${d.lang===k?'selected':''}>${n}</option>`).join('')}</select></label></div><label id="p-template-label">${t('body')}</label>${toolbar()}<div id="template-editor" class="rich-editor p-template-editor" contenteditable="true" role="textbox" aria-multiline="true" aria-labelledby="p-template-label">${R.safeHTML(d.html)}</div><button class="btn btn-primary" type="submit">${t('save')}</button></form></section><section><h2>${R.t('Saxlanmış şablonlar')}</h2>${tabs('pGroup',P.group)}${['CT','MR','CR','US'].filter(k=>P.group==='all'||P.group===k).map(k=>`<section class="card p-template-group"><h3>${groupName(k)} <span class="badge muted">${list.filter(s=>s.modality===k).length}</span></h3>${list.filter(s=>s.modality===k).map(s=>`<article class="p-template-item"><div><strong>${E(s.title)}</strong><small>${E(s.lang.toUpperCase())}</small></div><div class="p-template-preview">${R.safeHTML(s.html)}</div><div class="button-row">${button(t('edit'),'pEditTemplate',`data-id="${E(s.id)}"`)}${button(R.t('Sil'),'xDeleteTemplate',`data-id="${E(s.id)}"`)}</div></article>`).join('')||`<p class="muted-text">${t('empty')}</p>`}</section>`).join('')}</section></div>`);
  };
  R.actions.pGroup=el=>{readDraft();P.group=el.dataset.group;R.render();};
  R.actions.pNewTemplate=()=>{P.draft={title:'',modality:P.group==='all'?'CT':P.group,lang:R.lang,html:''};R.render();};
  R.actions.pEditTemplate=el=>{const template=X.templates?.find(s=>s.id===el.dataset.id);if(template){P.draft={...template};R.render();R.$('#template-editor')?.focus();}};
  R.forms.pTemplate=async()=>{readDraft();const d=P.draft;if(!R.$('#template-editor').textContent.trim())throw Error(t('body'));if(live())await R.request('/x/templates'+(d.id?'/'+encodeURIComponent(d.id):''),{method:d.id?'PUT':'POST',body:d});else{const all=X.memory.templates;const value={...d,id:d.id||R.id('tpl'),owner:R.state.user.id,html:R.safeHTML(d.html)};const at=all.findIndex(s=>s.id===d.id&&s.owner===R.state.user.id);if(at<0)all.push(value);else all[at]=value;}X.templates=await X.req('/templates');P.draft={title:'',modality:d.modality,lang:d.lang,html:''};R.render();R.toast(t('saved'));};
  function templateCommand(cmd,value){const ed=R.$('#template-editor');if(!ed)return;ed.focus();if(P.range&&ed.contains(P.range.commonAncestorContainer)){const sel=getSelection();sel.removeAllRanges();sel.addRange(P.range);}if(cmd==='table'){cmd='insertHTML';value='<table><tbody><tr><td><br></td><td><br></td></tr><tr><td><br></td><td><br></td></tr></tbody></table><p><br></p>';}document.execCommand(cmd,false,value);if(getSelection().rangeCount)P.range=getSelection().getRangeAt(0).cloneRange();readDraft();}
  document.addEventListener('mousedown',e=>{if(e.target.closest('[data-template-cmd]'))e.preventDefault();});
  document.addEventListener('click',e=>{const b=e.target.closest('[data-template-cmd]');if(b)templateCommand(b.dataset.templateCmd);});
  document.addEventListener('change',e=>{if(e.target.id==='p-template-heading')templateCommand('formatBlock',e.target.value);});
  for(const event of ['keyup','mouseup','input'])document.addEventListener(event,e=>{if(e.target.closest('#template-editor')){if(getSelection().rangeCount)P.range=getSelection().getRangeAt(0).cloneRange();if(event==='input')readDraft();}});
  document.addEventListener('paste',e=>{if(e.target.closest('#template-editor')){e.preventDefault();templateCommand('insertText',e.clipboardData.getData('text/plain'));}});
  const picker=()=>`${tabs('pPickGroup',P.pickGroup||'all')}${['CT','MR','CR','US'].filter(k=>!P.pickGroup||P.pickGroup==='all'||P.pickGroup===k).map(k=>`<section class="p-picker-group"><h3>${groupName(k)}</h3>${(X.templates||[]).filter(s=>s.modality===k).map(s=>`<div class="x-queue-row"><span><strong>${E(s.title)}</strong><small>${E(s.lang.toUpperCase())}</small></span>${button(t('insert'),'xInsertTemplate',`data-id="${E(s.id)}"`)}</div>`).join('')||`<p>${t('empty')}</p>`}</section>`).join('')}`;
  R.actions.xPickTemplate=async()=>{X.templates=await X.req('/templates');P.pickGroup='all';R.modal(t('templateLibrary'),picker(),true);};
  R.actions.pPickGroup=el=>{P.pickGroup=el.dataset.group;R.modal(t('templateLibrary'),picker(),true);};
  if(live()){
    const productionText={
      'Demo profil':['Radioloq','Радиолог','Radiologist'],
      'Nümunə profil':['','', ''],
      'demo konsultasiya qiyməti':['konsultasiya qiyməti','стоимость консультации','consultation price'],
      'Təqdimat demosudur. Nümunə profillər və qiymətlər real xidmət təklifi deyil.':['Yalnız administrator tərəfindən təsdiqlənmiş həkimlər göstərilir.','Показаны только подтверждённые администратором врачи.','Only doctors approved by the administrator are listed.'],
      'Yalnız ödənişi təsdiqlənmiş və sizə aid müraciətlər göstərilir.':['Yalnız sizə təyin olunmuş müraciətlər göstərilir.','Показаны только назначенные вам заявки.','Only cases assigned to you are shown.'],
      'Məlumatları yoxlayın. Ödəniş təsdiqindən sonra müraciət həkimin kabinetinə düşür.':['Məlumatları yoxlayıb göndərin. Müraciət seçdiyiniz həkimin kabinetinə düşür.','Проверьте и отправьте данные. Заявка поступит выбранному врачу.','Review and submit your details. The selected doctor receives your request.'],
      'Lokal sınaq serveridir. Real pasiyent və həssas hesab məlumatlarını daxil etməyin.':['Hesabınıza təhlükəsiz giriş edin.','Войдите в свою учётную запись.','Sign in to your account.'],
      'Demo şərtləri':['Məxfilik məlumatı','Информация о конфиденциальности','Privacy information'],
      'ilə tanışam və yalnız sınaq məlumatı daxil edirəm.':['ilə tanışam.','мне известна.','has been reviewed.'],
      'Həkim profili administrator təsdiqindən sonra açıq siyahıda görünür. Demo şifrəsi başqa hesablarınızla eyni olmasın.':['Həkim profili administrator təsdiqindən sonra açıq siyahıda görünür.','Профиль врача появится после подтверждения администратором.','Doctor profiles appear after administrator approval.'],
    };
    for(const [key,values] of Object.entries(productionText))['az','ru','en'].forEach((lang,i)=>{window.RADAZ_MESSAGES[lang][key]=values[i];});
    R.api.createCase=async(data,archive)=>{const form=new FormData();form.append('payload',JSON.stringify({...data,sample:false}));if(archive)form.append('archive',archive,archive.name||'dicom.zip');return R.request('/consultations',{method:'POST',body:form});};
    R.actions.checkout=async()=>{if(R.state.busy)return;if(!R.$('#demo-ack')?.checked)throw Error(t('confirmSubmit'));R.state.busy=true;try{const data={patient:R.state.patient,doctor_id:R.state.doctorId,slot_id:R.state.slotId,consent:true,metadata:R.state.uploadMeta||{}};R.state.receipt=await R.api.createCase(data,R.state.archive);R.state.checkout=null;R.go('/success');}finally{R.state.busy=false;}};
    R.successPage=()=>{const r=R.state.receipt;if(!r)return `<main class="container page"><a href="#/consult">${t('submit')}</a></main>`;return `<main class="container page p-receipt"><h1>${t('requestReceived')}</h1><p>${t('notCharged')}</p><section class="card"><h3>${R.t('Müraciət kodu')}</h3><p>${E(r.case.id)}</p><h3>${R.t('Gizli giriş açarı')}</h3><code>${E(r.token)}</code><p>${R.t('Bu açarı saxlayın. Başqası ilə paylaşmayın. Səhifəni yeniləsəniz, burada yenidən göstərilməyə bilər.')}</p>${button(R.t('Giriş məlumatını saxla'),'downloadReceipt')}<a class="btn btn-primary" href="#/track">${R.t('Müraciəti izlə')}</a></section></main>`;};
    R.actions.downloadReceipt=()=>{const r=R.state.receipt;R.download(`RADAZ\n${r.case.id}\n${r.token}\n`,r.case.id+'-giris.txt');};
    const header=R.header;R.header=()=>{const el=document.createElement('div');el.innerHTML=header();el.querySelector('.demo-strip')?.remove();el.querySelector('[data-action="demoLogin"]')?.remove();return el.innerHTML;};
    const auth=R.authPage;R.authPage=register=>{const el=document.createElement('div');el.innerHTML=auth(register);el.querySelectorAll('[data-action="demoLogin"],[data-action="demoAdmin"],.auth-divider').forEach(e=>e.remove());el.querySelector('[name="role"][value="patient"]')?.closest('label')?.remove();const p=el.querySelector('[name="password"]');if(register&&p)p.minLength=12;el.querySelector('[name="code"]')?.closest('label')?.remove();return el.innerHTML;};
    const consult=R.consultPage;R.consultPage=()=>{const el=document.createElement('div');el.innerHTML=consult();el.querySelector('[data-action="useSample"]')?.remove();el.querySelectorAll('[data-action]').forEach(b=>{if(b.textContent.includes('Fayl olmadan')||['demoFiles','sampleStudy'].includes(b.dataset.action))b.remove();});const ack=el.querySelector('#demo-ack');if(ack){const label=ack.closest('label');label.innerHTML='<input id="demo-ack" type="checkbox"><span>'+t('confirmSubmit')+'</span>';const panel=label.closest('.payment-demo-box');if(panel)panel.querySelectorAll('h3,p').forEach(n=>n.textContent=t('notCharged'));}const checkout=el.querySelector('[data-action="checkout"]');if(checkout)checkout.textContent=t('submit');return el.innerHTML;};
  }
  const originalRender=R.render;
  R.render=()=>{
    if(R.state.route.startsWith('/admin/')){R.$('#app').innerHTML=P.adminPage();document.title=t('payments')+' · RADAZ';}
    else originalRender();
    if(R.state.route.startsWith('/images/'))document.title=t('images')+' · RADAZ';
    if(R.state.route==='/templates')document.title=t('templateLibrary')+' · RADAZ';
    R.$$('.dashboard-sidebar nav').forEach(nav=>{if(R.state.user?.role==='admin'&&!nav.querySelector('[href="#/admin/payments"]'))nav.insertAdjacentHTML('beforeend',`<a href="#/admin/payments">${R.icon('lock',18)} ${t('payments')}</a><a href="#/admin/viewer">${R.icon('scan',18)} ${t('viewerSettings')}</a>`);});
    R.$$('a[href^="#/workspace/"]').forEach(a=>{a.href=a.getAttribute('href').replace('#/workspace/','#/report/');});
    if(live()){
      R.$$('.demo-workspace-banner,.workspace-demo,[data-action="demoAdmin"],[data-action="xOperator"],[data-action="demoDelivery"]').forEach(el=>el.remove());
      R.$$('.delivery-note').forEach(el=>el.textContent=R.t('Hesabat təsdiqlənib'));
      if(R.state.route==='/security')R.$$('.x-plan-grid').forEach(el=>{el.querySelectorAll('form').forEach(f=>f.remove());});
      if(R.state.route==='/consult'){const b=R.$('[data-action="checkout"]');if(b)b.textContent=t('submit');}
    }
  };
  for(const name of ['login','logout','register','demoLogin']){const fn=R.api[name];R.api[name]=async(...args)=>{const result=await fn(...args);P.settings=null;P.settingsError='';P.viewer=null;P.draft={title:'',modality:'CT',lang:R.lang,html:''};return result;};}
  if(R.$('#app').children.length)R.render();
})();
